  ('de_bnetza_smard_2025', 'Bundesnetzagentur — press release «Bundesnetzagentur publishes 2025 electricity market data» (4 January 2026)', 'The federal network agency''s yearly summary of the SMARD data: generation, consumption, the mean day-ahead wholesale price of 2025 and of 2024, the hours of negative prices.', 'text', 'https://www.bundesnetzagentur.de/SharedDocs/Pressemitteilungen/EN/2026/20260104_SMARD.html', null, 'none', array['DE']::text[], '{}'::text[], 'Terms not stated', null, null, false, 'pack:de'),
  ('de_eeg_2023', 'Erneuerbare-Energien-Gesetz (EEG 2023)', 'The renewable energy sources act: the market premium and its tenders (§ 22), the feed-in tariff (§ 21), the tenant electricity premium (§ 21 (3)), the duration of payment (§ 25), the reduction to zero while the spot price is negative (§ 51).', 'text', 'https://www.gesetze-im-internet.de/eeg_2014/', null, 'none', array['DE']::text[], '{}'::text[], 'Terms not stated', 'Bundesministerium der Justiz — gesetze-im-internet.de', null, false, 'pack:de'),
  ('de_entsoe_eic_codes', 'ENTSO-E — list of Y EIC codes (areas)', 'The list of area codes of the European electricity market, with their functions: bidding zone, control area, LFC area, scheduling area.', 'text', 'https://eepublicdownloads.blob.core.windows.net/cio-lio/csv/Y_eicCodes.csv', null, 'none', array['DE']::text[], '{}'::text[], 'Terms not stated', null, null, false, 'pack:de'),
  ('de_entsoe_x_eic_codes', 'ENTSO-E — list of X EIC codes (parties)', 'The list of party codes of the European electricity market, the system operators among them.', 'text', 'https://eepublicdownloads.blob.core.windows.net/cio-lio/csv/X_eicCodes.csv', null, 'none', array['DE']::text[], '{}'::text[], 'Terms not stated', null, null, false, 'pack:de'),
  ('de_enwg', 'Energiewirtschaftsgesetz (EnWG)', 'The energy industry act: tenant electricity contracts (§ 42a), shared supply within a building (§ 42b), shared use of renewable electricity through the distribution grid (§ 42c).', 'text', 'https://www.gesetze-im-internet.de/enwg_2005/', null, 'none', array['DE']::text[], '{}'::text[], 'Terms not stated', 'Bundesministerium der Justiz — gesetze-im-internet.de', null, false, 'pack:de'),
  ('de_eurostat_business_prices', 'Eurostat — electricity prices components for non-household consumers, annual (nrg_pc_205_c)', 'Yearly electricity prices of non-household consumers by consumption band and component.', 'text', 'https://ec.europa.eu/eurostat/databrowser/view/nrg_pc_205_c/default/table', null, 'none', array['DE']::text[], '{}'::text[], 'CC-BY-4.0', '© European Union, Eurostat', null, true, 'pack:de'),
  ('de_eurostat_household_prices', 'Eurostat — electricity prices components for household consumers, annual (nrg_pc_204_c)', 'Yearly electricity prices of households by consumption band and component: energy and supply, network costs, taxes and levies, VAT.', 'text', 'https://ec.europa.eu/eurostat/databrowser/view/nrg_pc_204_c/default/table', null, 'none', array['DE']::text[], '{}'::text[], 'CC-BY-4.0', '© European Union, Eurostat', null, true, 'pack:de'),
  ('de_mastr_numbering', 'Marktstammdatenregister — MaStR-Nummernkonzept (May 2019)', 'The federal network agency''s note on how the numbers of the register are built: a three-letter prefix of the kind of object or market function, the version digit 9, ten random digits and an EAN check digit.', 'text', 'https://www.marktstammdatenregister.de/MaStRHilfe/files/regHilfen/MaStR-Nummernkonzept.pdf', null, 'none', array['DE']::text[], '{}'::text[], 'Terms not stated', null, null, false, 'pack:de'),
  ('de_msbg', 'Messstellenbetriebsgesetz (MsbG)', 'The metering point operation act: who runs a meter, the roll-out of smart metering systems, and how energy is measured (§ 55: quarter-hourly metered load profiles).', 'text', 'https://www.gesetze-im-internet.de/messbg/', null, 'none', array['DE']::text[], '{}'::text[], 'Terms not stated', 'Bundesministerium der Justiz — gesetze-im-internet.de', null, false, 'pack:de'),
  ('de_stromstg', 'Stromsteuergesetz (StromStG)', 'The electricity tax act: the tax rate per megawatt hour (§ 3) and its reliefs.', 'text', 'https://www.gesetze-im-internet.de/stromstg/__3.html', null, 'none', array['DE']::text[], '{}'::text[], 'Terms not stated', 'Bundesministerium der Justiz — gesetze-im-internet.de', null, false, 'pack:de'),
  ('de_uba_co2_electricity_2024', 'Umweltbundesamt — CO2-Emissionen pro Kilowattstunde Strom 2024', 'The environment agency''s yearly figure of the CO2 emitted in generating each kilowatt hour of electricity consumed in Germany, from its report on the specific greenhouse gas emissions of the German electricity mix.', 'text', 'https://www.umweltbundesamt.de/themen/co2-emissionen-pro-kilowattstunde-strom-2024', null, 'none', array['DE']::text[], '{}'::text[], 'Terms not stated', null, null, false, 'pack:de'),
  ('de_ustg', 'Umsatzsteuergesetz (UStG)', 'The VAT act: the standard rate (§ 12 (1)) and the zero rate on the supply and installation of photovoltaic systems on or near dwellings (§ 12 (3)).', 'text', 'https://www.gesetze-im-internet.de/ustg_1980/__12.html', null, 'none', array['DE']::text[], '{}'::text[], 'Terms not stated', 'Bundesministerium der Justiz — gesetze-im-internet.de', null, false, 'pack:de'),
  ('destatis_gv_isys', 'Destatis — Gemeindeverzeichnis-Informationssystem (GV-ISys)', 'The statistics office''s register of the municipalities of Germany, with their official key (AGS) under their state, government district and district, published quarterly.', 'file', 'https://www.destatis.de/DE/Themen/Laender-Regionen/Regionales/Gemeindeverzeichnis/_inhalt.html', null, 'none', array['DE']::text[], '{}'::text[], 'Datenlizenz Deutschland – Namensnennung – Version 2.0 (not verified)', '© Statistisches Bundesamt (Destatis)', null, true, 'pack:de'),
  ('mastr', 'Marktstammdatenregister', 'The register of the federal network agency where every grid-connected generation unit, storage unit and market actor of the German electricity and gas markets is registered, with its number, place, power and commissioning date; public data downloadable in full.', 'registry', 'https://www.marktstammdatenregister.de/MaStR', 'https://www.marktstammdatenregister.de/MaStRHilfe/', 'none', array['DE']::text[], '{}'::text[], 'Datenlizenz Deutschland – Namensnennung – Version 2.0 (not verified)', '© Bundesnetzagentur — Marktstammdatenregister', null, true, 'pack:de'),
  ('netztransparenz', 'Netztransparenz — the platform of the four transmission system operators', 'The joint publications of the German transmission system operators: balancing, the market value of renewables, the EEG account, the surcharges and levies of the grid, by control area.', 'api', 'https://www.netztransparenz.de/', null, 'none', array['DE']::text[], '{}'::text[], 'Terms not stated', null, null, false, 'pack:de'),
