-- project_kinds: 4. The frames of projects the law of the country defines, each refining a kind of the core.
insert into project_kinds (code, name, description, parent_code, country, source_code, reference, published_by) values
  ('de_buergerenergiegesellschaft', 'Bürgerenergiegesellschaft', 'A citizens'' energy company: a cooperative or other company of at least 50 natural persons with voting rights, at least 75 % of the votes held by natural persons registered in a postal code area wholly or partly within 50 km of the planned installation, the other votes held only by small and medium enterprises or municipalities, and no member above 10 % of the votes; it may be exempted from tenders.', 'energy_community', 'DE', 'de_eeg_2023', 'EEG 2023, § 3 number 15 (definition) and § 22 (2) and (3) (exemption from tenders)', 'pack:de'),
  ('de_gemeinsame_nutzung', 'Gemeinsame Nutzung (Energy Sharing)', 'Energy sharing through the distribution grid: the operator of a renewable installation, or of a storage fed from renewables only — a natural person, or a company whose members are all final consumers or public bodies — supplies other final consumers (households, small and medium enterprises, public bodies) through the public distribution grid under a supply contract and a sharing contract that sets an allocation key; every consumption point and the installation are metered quarter-hourly.', 'collective_self_consumption', 'DE', 'de_enwg', 'EnWG § 42c (1) to (3)', 'pack:de'),
  ('de_gemeinschaftliche_gebaeudeversorgung', 'Gemeinschaftliche Gebäudeversorgung', 'Shared supply within a building: final consumers of one building use, under a building electricity use contract, the electricity of an installation on, at or in that building, without passing through a grid, each receiving the share of an allocation key per 15-minute interval; the operator does not owe them their full supply.', 'collective_self_consumption', 'DE', 'de_enwg', 'EnWG § 42b (1) and (5)', 'pack:de'),
  ('de_mieterstrom', 'Mieterstrom', 'Tenant electricity: electricity from a solar installation on, at or in a building, supplied by its operator or a third party to final consumers in that building, its ancillary buildings or buildings of the same neighbourhood, without passing through a grid, under a supply contract that also covers the rest of their needs.', 'collective_self_consumption', 'DE', 'de_eeg_2023', 'EEG 2023, § 21 (3) (the tenant electricity premium and its perimeter); the supply contract is EnWG § 42a', 'pack:de')
on conflict (code) do update set
