-- grid.support_schemes: 3. Who a scheme supports, for how long, and when it stops at negative prices.
insert into grid.support_schemes (code, country, name, kind, allocation, device_types, min_power_kw, max_power_kw, duration_years, negative_price_rules, source_code, reference, valid_from, valid_to, published_by) values
  ('de_eeg_feed_in_tariff', 'DE', 'Einspeisevergütung (EEG)', 'feed_in_tariff', 'open_window', '{}'::text[], null, 100, 20, '[{"threshold_kw":100,"valid_from":"2026-11-07","reference":"EEG 2023, § 51 (1) and (2), as in force when read: for periods in which the spot market price is negative, the value the payment is computed from falls to zero. Not applied to an installation below 100 kW until the end of the calendar year in which it is equipped with a smart metering system, nor to one below 2 kW until the end of the year the federal network agency issues its determination under § 85 (2) number 12. The rule applies by the wording in force when the installation was commissioned (§ 100); earlier wordings (several consecutive hours of negative prices, larger installations) are not loaded, so the date is the day the wording was read, not the day it came into force"}]'::jsonb, 'de_eeg_2023', 'EEG 2023, § 19 (1) number 2 and § 21 (1) number 1: a feed-in tariff for installations of up to 100 kW whose value the law sets; § 25 (1): paid for 20 years, extended to 31 December of the twentieth year', null::date, null::date, 'pack:de'),
  ('de_eeg_market_premium', 'DE', 'Marktprämie (EEG), statutory value', 'contract_for_difference', 'open_window', '{}'::text[], null, null, 20, '[{"threshold_kw":100,"valid_from":"2026-11-07","reference":"EEG 2023, § 51 (1) and (2), as in force when read: for periods in which the spot market price is negative, the value the payment is computed from falls to zero. Not applied to an installation below 100 kW until the end of the calendar year in which it is equipped with a smart metering system, nor to one below 2 kW until the end of the year the federal network agency issues its determination under § 85 (2) number 12. The rule applies by the wording in force when the installation was commissioned (§ 100); earlier wordings (several consecutive hours of negative prices, larger installations) are not loaded, so the date is the day the wording was read, not the day it came into force"}]'::jsonb, 'de_eeg_2023', 'EEG 2023, § 19 (1) number 1 and § 22 (5): the sliding market premium on directly marketed electricity whose value the law sets (§§ 40 to 49), for installations exempt from tenders — solar of the first segment up to 1 MW, of the second segment up to 750 kW, onshore wind up to 1 MW, biomass up to 150 kW, citizens'' energy companies within § 22b; § 25 (1): 20 years. A premium that is never negative, which the kind contract_for_difference approximates', null::date, null::date, 'pack:de'),
  ('de_eeg_tender', 'DE', 'Ausschreibungen (EEG)', 'contract_for_difference', 'tender', '{}'::text[], null, null, 20, '[{"threshold_kw":100,"valid_from":"2026-11-07","reference":"EEG 2023, § 51 (1) and (2), as in force when read: for periods in which the spot market price is negative, the value the payment is computed from falls to zero. Not applied to an installation below 100 kW until the end of the calendar year in which it is equipped with a smart metering system, nor to one below 2 kW until the end of the year the federal network agency issues its determination under § 85 (2) number 12. The rule applies by the wording in force when the installation was commissioned (§ 100); earlier wordings (several consecutive hours of negative prices, larger installations) are not loaded, so the date is the day the wording was read, not the day it came into force"}]'::jsonb, 'de_eeg_2023', 'EEG 2023, § 22 (1) to (4): the federal network agency sets by tender who is entitled to the market premium and its value, for onshore wind, solar, biomass, green hydrogen and offshore wind above the thresholds of § 22 (2) to (4); § 25 (1): 20 years', null::date, null::date, 'pack:de')
on conflict (code) do update set
  country              = excluded.country,
  name                 = excluded.name,
  kind                 = excluded.kind,
  allocation           = excluded.allocation,
  device_types         = excluded.device_types,
  min_power_kw         = excluded.min_power_kw,
  max_power_kw         = excluded.max_power_kw,
  duration_years       = excluded.duration_years,
  negative_price_rules = excluded.negative_price_rules,
  source_code          = excluded.source_code,
  reference            = excluded.reference,
  valid_from           = excluded.valid_from,
  valid_to             = excluded.valid_to
where support_schemes.published_by = excluded.published_by;

