      ('control_area'::text, 'DE-MV'::text, '{}'::jsonb, '"10YDE-VE-------2"'::jsonb, 'code'::text, '2026-11-07'::date, null::date, 'de_50hertz_grid_area'::text, 'The 50Hertz grid area covers Brandenburg, Mecklenburg-Vorpommern, Saxony, Saxony-Anhalt and Thuringia and the city states of Berlin and Hamburg; its control area is row 10YDE-VE-------2 (DE-50HERTZ, Control Area) of the ENTSO-E list of Y EIC codes'::text, 'published'::text),
      ('control_area'::text, 'DE-SN'::text, '{}'::jsonb, '"10YDE-VE-------2"'::jsonb, 'code'::text, '2026-11-07'::date, null::date, 'de_50hertz_grid_area'::text, 'The 50Hertz grid area covers Brandenburg, Mecklenburg-Vorpommern, Saxony, Saxony-Anhalt and Thuringia and the city states of Berlin and Hamburg; its control area is row 10YDE-VE-------2 (DE-50HERTZ, Control Area) of the ENTSO-E list of Y EIC codes'::text, 'published'::text),
      ('control_area'::text, 'DE-ST'::text, '{}'::jsonb, '"10YDE-VE-------2"'::jsonb, 'code'::text, '2026-11-07'::date, null::date, 'de_50hertz_grid_area'::text, 'The 50Hertz grid area covers Brandenburg, Mecklenburg-Vorpommern, Saxony, Saxony-Anhalt and Thuringia and the city states of Berlin and Hamburg; its control area is row 10YDE-VE-------2 (DE-50HERTZ, Control Area) of the ENTSO-E list of Y EIC codes'::text, 'published'::text),
