      ('energy_price_household'::text, null::text, '{}'::jsonb, '165.4'::jsonb, 'EUR-PER-MegaW-HR'::text, '2024-01-01'::date, '2025-01-01'::date, 'de_eurostat_household_prices'::text, 'nrg_pc_204_c, Germany, 2024, band KWH2500-4999, component NRG_SUP: 0.1654 EUR/kWh'::text, 'published'::text),
      ('energy_price_household'::text, null::text, '{}'::jsonb, '148.1'::jsonb, 'EUR-PER-MegaW-HR'::text, '2025-01-01'::date, null::date, 'de_eurostat_household_prices'::text, 'nrg_pc_204_c, Germany, 2025, band KWH2500-4999, component NRG_SUP: 0.1481 EUR/kWh'::text, 'published'::text),
      ('grid_co2_factor'::text, null::text, '{}'::jsonb, '0.363'::jsonb, 'KiloGM-PER-KiloW-HR'::text, '2024-01-01'::date, null::date, 'de_uba_co2_electricity_2024'::text, 'Page text of 9 April 2025: 363 g CO2 emitted on average in 2024 in generating each kilowatt hour of electricity consumed in Germany (386 in 2023, 433 in 2022)'::text, 'published'::text),
