      ('injection_price_reference'::text, null::text, '{}'::jsonb, '89.32'::jsonb, 'EUR-PER-MegaW-HR'::text, '2025-01-01'::date, null::date, 'de_bnetza_smard_2025'::text, 'Section «Wholesale electricity prices»: the average day-ahead wholesale price in 2025, 89.32 €/MWh'::text, 'published'::text),
