      ('metering_step'::text, null::text, '{}'::jsonb, '"PT15M"'::jsonb, 'ISO8601-duration'::text, '2026-11-07'::date, null::date, 'de_msbg'::text, '§ 55 (1) numbers 1 to 3: a final consumer above 100 000 kWh a year, or equipped with a smart metering system, is measured by a metered load profile (Zählerstandsgangmessung) or a quarter-hourly registered load profile; any other final consumer by the energy taken, as its supply contract requires (§ 55 (1) number 4), which gives index readings only'::text, 'published'::text),
      ('offpeak_hours'::text, null::text, '{}'::jsonb, null::jsonb, 'hours'::text, '2026-11-07'::date, null::date, 'de_enwg'::text, '§ 14a (1): the federal network agency may set, by determination, uniform rules under which distribution operators reduce the network charges of controllable consumption devices in return for grid-oriented control, including economic incentives with a time granularity; no single national off-peak window follows from the act. The determination itself and the operators'' time windows were not read'::text, 'published'::text),
      ('sharing_settlement_period'::text, null::text, '{"project_kind":"de_gemeinschaftliche_gebaeudeversorgung"}'::jsonb, '"PT15M"'::jsonb, 'ISO8601-duration'::text, '2026-11-07'::date, null::date, 'de_enwg'::text, '§ 42b (5): the electricity of the building installation is allocated by 15-minute interval, limited in each interval to the smaller of what the installation generates and what the participating consumers use, and to each consumer''s own use'::text, 'published'::text),
      ('vat_rate_electricity'::text, null::text, '{}'::jsonb, '0.19'::jsonb, 'UNITLESS'::text, '2026-11-07'::date, null::date, 'de_ustg'::text, '§ 12 (1): the tax is 19 % of the taxable amount of every taxable supply; the supply of electricity has no reduced rate. A ratio kept for simulation; the rate holds since 1 January 2007, and the row starts on the day it was read'::text, 'published'::text)
  ),
  problems (problem) as (
    select format('attribute_type_unknown: %s is not an attribute_types code', p.attribute_type)
      from pack p
     where not exists (select 1 from attribute_types d where d.code = p.attribute_type)
    union all
    select format('unit_mismatch: %s is stored in %s and the pack says %s', p.attribute_type, u.unit, p.unit)
      from pack p
      join attribute_types d on d.code = p.attribute_type
      join quantities q on q.code = d.quantity_code
      cross join lateral (select quantity_unit(q.code, (select c.currency from countries c where c.code = 'DE')) as unit) u
     where u.unit <> p.unit
    union all
    select format('value_edited: %s%s from %s holds %s and the pack says %s; close it with valid_to and add a row',
                  p.attribute_type, coalesce(' (' || nullif(concat_ws(', ', p.region, nullif(p.condition, '{}')::text), '') || ')', ''), p.valid_from,
                  coalesce(x.value::text, 'null'), coalesce(p.value::text, 'null'))
      from pack p
      join defaults x
        on x.country = 'DE' and x.attribute_type = p.attribute_type
       and x.region is not distinct from p.region and x.valid_from = p.valid_from
       and x.condition = p.condition
     where x.value is distinct from p.value
  ),
  written as (
    insert into defaults (attribute_type, country, region, condition, value, valid_from, valid_to,
                          source_code, reference, quality, published_by)
    select p.attribute_type, 'DE', p.region, p.condition, p.value, p.valid_from, p.valid_to,
           p.source_code, p.reference, p.quality, 'pack:de'
      from pack p
     where not exists (select 1 from problems)
    on conflict (country, region, attribute_type, condition, valid_from) do update set
      valid_to    = excluded.valid_to,
      source_code = excluded.source_code,
      reference   = excluded.reference,
      quality     = excluded.quality
    returning 1
  )
  select string_agg(problem, '; ' order by problem) into refused from problems;
  if refused is not null then
    raise exception '%', refused;
  end if;
end
$seed$;
